using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace GearLab {
 public static class Train60Tests {
  public static int Run(string folder){Directory.CreateDirectory(folder);var checks=new List<string>();var failures=new List<string>();Action<bool,string> c=(ok,msg)=>{if(ok)checks.Add(msg);else failures.Add(msg);};try{var t=TransmissionTrain.Example();var s=TrainSolver.Solve(t);c(s.Valid,"belt/cycloid scene "+string.Join(";",s.Errors));var output=s.States[t.Stages.Last().Id];c(Math.Abs(output.OutputGain+.025)<1e-10,"2*20=40 opposite direction");c(Math.Abs(output.OutputRpm+7.5)<1e-10,"300/40=7.5rpm");c(Math.Abs(output.OutputTorque-.35*40*.7*.7)<1e-10,"sequential efficiency .49, torque6.86Nm");c(Math.Abs(output.OutputPower-.35*300*Math.PI/30*.49)<1e-10,"train power conservation with losses");string file=Path.Combine(folder,"example.train.json");t.Save(file);var copy=TransmissionTrain.Read(file);c(copy.Stages.Count==2&&TrainSolver.Solve(copy).Valid,"train persistence");
   var branch=new TransmissionTrain();var a=new TrainStage{Name="A",Parameters=Engine.Starter(1),PowerShare=.4};var b=new TrainStage{Name="B",Parameters=Engine.Starter(2),PowerShare=.6};branch.Stages.Add(a);branch.Stages.Add(b);var bs=TrainSolver.Solve(branch,false);c(bs.Valid,"two-branch power split");c(Math.Abs(bs.States[a.Id].InputTorque-.14)<1e-10&&Math.Abs(bs.States[b.Id].InputTorque-.21)<1e-10,"torque split, not duplicated");a.PowerShare=.5;c(!TrainSolver.Solve(branch,false).Valid,"overallocated branch rejected");a.PowerShare=.4;a.Parent=b.Id;b.Parent=a.Id;c(!TrainSolver.Solve(branch,false).Valid,"cycles rejected");a.Parent="missing";b.Parent=null;c(!TrainSolver.Solve(branch,false).Valid,"missing source rejected");
   var negative=new TransmissionTrain();var first=new TrainStage{Parameters=Engine.Starter(1)};negative.Stages.Add(first);negative.Stages.Add(new TrainStage{Parameters=Engine.Starter(2),Parent=first.Id});var ns=TrainSolver.Solve(negative,false);c(ns.Valid&&ns.States.Values.Last().OutputRpm<0,"opposite rotation can feed legacy belt stage");
   var rp=new TransmissionTrain();var rack=new TrainStage{Parameters=Engine.Starter(12)};var next=new TrainStage{Parameters=Engine.Starter(1),Parent=rack.Id};rp.Stages.Add(rack);rp.Stages.Add(next);c(!TrainSolver.Solve(rp,false).Valid,"rotary after linear rejected");
   foreach(var part in s.Scene.Model.Parts)c(PartMotion.Bind(s.Scene,part).At(.7,0).HasInverse,"train part animation "+part.Id);File.WriteAllText(Path.Combine(folder,"train.assembly.json"),CADDocument.Serializer().Serialize(TransmissionExport.Spec(s.Scene.Model)));
  }catch(Exception ex){failures.Add(ex.ToString());}File.WriteAllText(Path.Combine(folder,"train60-results.json"),CADDocument.Serializer().Serialize(new{Passed=failures.Count==0,Checks=checks.Count,Failures=failures}));return failures.Count==0?0:1;}
 }
}
